from decimal import Decimal

import pytest

from refproj.pricing import format_price, parse_price


def test_format_always_prints_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"


def test_format_prints_zero_as_zero_point_zero_zero() -> None:
    assert format_price(Decimal("0")) == "0.00"


def test_format_groups_thousands_by_commas() -> None:
    assert format_price(Decimal("1234.5")) == "1,234.50"


def test_format_prints_no_comma_below_a_thousand() -> None:
    assert format_price(Decimal("999.99")) == "999.99"


def test_format_groups_every_three_digits_up_to_max_price() -> None:
    assert format_price(Decimal("1000000.00")) == "1,000,000.00"
    assert format_price(Decimal("9999999.99")) == "9,999,999.99"


@pytest.mark.parametrize("price", [Decimal("10000000.00"), Decimal("-0.01")])
def test_format_rejects_a_price_outside_the_range(price: Decimal) -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(price)


@pytest.mark.parametrize("price", [Decimal("12.345"), Decimal("0.001")])
def test_format_rejects_a_fraction_of_a_cent_instead_of_rounding(price: Decimal) -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(price)


def test_parse_reads_a_grouped_price_in_cents() -> None:
    assert str(parse_price("1,234.50")) == "1234.50"


def test_parse_reads_a_price_with_the_commas_left_out_in_cents() -> None:
    assert str(parse_price("1234.50")) == "1234.50"


def test_parse_reads_the_bounds_of_the_range_in_cents() -> None:
    assert str(parse_price("0.00")) == "0.00"
    assert str(parse_price("9,999,999.99")) == "9999999.99"
    assert str(parse_price("9999999.99")) == "9999999.99"


